#include "price_monitor.hpp"
#include <memory>
namespace ir::alerts {
namespace {
struct Stmt {sqlite3_stmt*p=nullptr;Stmt(sqlite3*d,const char*s){if(sqlite3_prepare_v2(d,s,-1,&p,nullptr)!=SQLITE_OK)throw std::runtime_error("Monitor statement failed");}~Stmt(){sqlite3_finalize(p);}void text(int n,const std::string&s){sqlite3_bind_text(p,n,s.c_str(),-1,SQLITE_TRANSIENT);}void num(int n,int64_t v){sqlite3_bind_int64(p,n,v);}bool row(){int r=sqlite3_step(p);if(r!=SQLITE_ROW&&r!=SQLITE_DONE)throw std::runtime_error("Monitor storage failed");return r==SQLITE_ROW;}std::string str(int n){return reinterpret_cast<const char*>(sqlite3_column_text(p,n));}};
Rule load(const json&j){Rule r;r.id=j.at("id");r.instrument=j.at("instrument");r.currency=j.at("currency");r.venue=j.at("venue");r.feed=j.at("feed");r.basis=j.at("basis");r.mode=j.at("mode");r.target=j.at("targetUnits");r.maxAge=j.at("maxAge");r.armed=j.at("armed");r.generation=j.at("generation");r.email=j.at("email");return r;}
}
void Monitor::sql(const char*s){if(sqlite3_exec(db,s,nullptr,nullptr,nullptr)!=SQLITE_OK)throw std::runtime_error("Monitor transaction failed");}
Monitor::Monitor(const std::string&path){if(sqlite3_open(path.c_str(),&db)!=SQLITE_OK)throw std::runtime_error("Cannot open monitor database");sqlite3_busy_timeout(db,5000);sql("PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL;");Stmt version(db,"PRAGMA user_version");version.row();if(sqlite3_column_int(version.p,0)>1)throw std::runtime_error("Monitor database requires newer application");sql("CREATE TABLE IF NOT EXISTS alert_rules(id TEXT PRIMARY KEY,body TEXT NOT NULL); CREATE TABLE IF NOT EXISTS alert_events(id TEXT PRIMARY KEY,body TEXT NOT NULL); CREATE TABLE IF NOT EXISTS delivery_outbox(id TEXT PRIMARY KEY,body TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,due INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending'); CREATE TABLE IF NOT EXISTS delivery_attempts(id TEXT,at INTEGER,accepted INTEGER); PRAGMA user_version=1;");}
Monitor::~Monitor(){sqlite3_close(db);}
json Monitor::snapshot(){std::lock_guard lock(mu);json j={{"health",health},{"instruments",instruments()},{"rules",json::array()},{"events",json::array()},{"deliveries",json::array()}};for(auto table:{"alert_rules","alert_events"}){std::string query="SELECT body FROM "+std::string(table)+" ORDER BY rowid DESC LIMIT 200";Stmt s(db,query.c_str());while(s.row())j[std::string(table)=="alert_rules"?"rules":"events"].push_back(json::parse(s.str(0)));}Stmt d(db,"SELECT id,status,attempts FROM delivery_outbox ORDER BY rowid DESC LIMIT 100");while(d.row())j["deliveries"].push_back({{"id",d.str(0)},{"status",d.str(1)},{"attempts",sqlite3_column_int(d.p,2)}});return j;}
json Monitor::save(const json&j){std::lock_guard lock(mu);Rule r=parseRule(j);if(r.id.empty()){Stmt s(db,"SELECT lower(hex(randomblob(16)))");s.row();r.id=s.str(0);}else{Stmt old(db,"SELECT body FROM alert_rules WHERE id=?");old.text(1,r.id);if(!old.row())throw std::invalid_argument("Unknown rule");r.generation=load(json::parse(old.str(0))).generation+1;}auto body=ruleJson(r);Stmt s(db,"INSERT OR REPLACE INTO alert_rules VALUES(?,?)");s.text(1,r.id);s.text(2,body.dump());s.row();states.erase(r.id);return body;}
void Monitor::action(const std::string&id,const std::string&a){std::lock_guard lock(mu);Stmt s(db,"SELECT body FROM alert_rules WHERE id=?");s.text(1,id);if(!s.row())throw std::invalid_argument("Unknown rule");auto r=load(json::parse(s.str(0)));if(a=="delete"){Stmt d(db,"DELETE FROM alert_rules WHERE id=?");d.text(1,id);d.row();}else{if(a!="pause"&&a!="rearm")throw std::invalid_argument("Unknown action");r.armed=a=="rearm";r.generation++;Stmt u(db,"UPDATE alert_rules SET body=? WHERE id=?");u.text(1,ruleJson(r).dump());u.text(2,id);u.row();}states.erase(id);}
void Monitor::observe(const Quote&q,int64_t now){std::lock_guard lock(mu);health["lastReceived"]=now;health["instrument"]=q.instrument;health["exchangeTime"]=q.exchangeTime;health["askUnits"]=q.ask?json(*q.ask):json(nullptr);health["venue"]=q.venue;health["feed"]=q.feed;health["session"]=q.session;health["delaySeconds"]=q.delaySeconds;
 Stmt s(db,"SELECT body FROM alert_rules");while(s.row()){auto r=load(json::parse(s.str(0)));if(r.instrument!=q.instrument)continue;auto result=evaluate(r,states[r.id],q,now);health["evaluation"]=result;if(result!="trigger")continue;
 auto id=r.id+":"+std::to_string(r.generation);auto event=ruleJson(r);event["id"]=id;event["ruleId"]=r.id;event["observedAt"]=q.exchangeTime;event["receivedAt"]=now;event["priceUnits"]=r.basis=="ASK"?*q.ask:*q.last;event["delaySeconds"]=q.delaySeconds;event["session"]=q.session;
 sql("BEGIN IMMEDIATE");try{Stmt e(db,"INSERT OR IGNORE INTO alert_events VALUES(?,?)");e.text(1,id);e.text(2,event.dump());e.row();if(sqlite3_changes(db)){for(auto channel:{"notification","email"}){if(std::string(channel)=="email"&&r.email.empty())continue;auto b=event;b["channel"]=channel;Stmt o(db,"INSERT INTO delivery_outbox(id,body) VALUES(?,?)");o.text(1,id+":"+channel);o.text(2,b.dump());o.row();}}r.armed=false;Stmt u(db,"UPDATE alert_rules SET body=? WHERE id=?");u.text(1,ruleJson(r).dump());u.text(2,r.id);u.row();sql("COMMIT");}catch(...){sql("ROLLBACK");throw;}}
}
void Monitor::disconnect(const std::string&reason){std::lock_guard lock(mu);states.clear();health={{"status",reason}};}
void Monitor::sourceHealth(const json&j){std::lock_guard lock(mu);health=j;}
json Monitor::claim(int64_t now){std::lock_guard lock(mu);json rows=json::array();sql("BEGIN IMMEDIATE");try{Stmt s(db,"SELECT id,body FROM delivery_outbox WHERE status IN ('pending','sending') AND due<=? AND attempts<5 LIMIT 10");s.num(1,now);while(s.row()){auto b=json::parse(s.str(1));b["deliveryId"]=s.str(0);rows.push_back(b);}for(auto b:rows){Stmt u(db,"UPDATE delivery_outbox SET status='sending',due=?,attempts=attempts+1 WHERE id=?");u.num(1,now+120);u.text(2,b["deliveryId"]);u.row();}sql("COMMIT");}catch(...){sql("ROLLBACK");throw;}return rows;}
void Monitor::complete(const std::string&id,bool ok,int64_t now){std::lock_guard lock(mu);sql("BEGIN IMMEDIATE");try{Stmt s(db,"UPDATE delivery_outbox SET status=CASE WHEN ? THEN 'accepted' WHEN attempts>=5 THEN 'failed' ELSE 'pending' END,due=?+(30 << min(attempts,5)) WHERE id=? AND status='sending'");s.num(1,ok);s.num(2,now);s.text(3,id);s.row();if(sqlite3_changes(db)){Stmt a(db,"INSERT INTO delivery_attempts VALUES(?,?,?)");a.text(1,id);a.num(2,now);a.num(3,ok);a.row();}sql("COMMIT");}catch(...){sql("ROLLBACK");throw;}}
}
